// Client-side search over the data generated by the SearchData pipeline (docs/src/Search/SearchData.cs).
// Usable in the browser (window.DocsSearch, requires MiniSearch) and in Node (module.exports) for testing.
(function (root, factory) {
    if (typeof module === "object" && module.exports) {
        module.exports = factory(require("minisearch"));
    } else {
        root.DocsSearch = factory(root.MiniSearch);
    }
})(this, function (MiniSearch) {
    "use strict";

    // Common words which are ignored if the query contains other words
    const STOP_WORDS = new Set([
        "a", "an", "and", "are", "as", "at", "be", "by", "can", "do", "does", "for", "from", "how", "i", "in", "is",
        "it", "of", "on", "or", "should", "that", "the", "this", "to", "we", "what", "when", "where", "which", "with",
    ]);

    const SEPARATOR = /[^\p{L}\p{N}]+/u;
    const EDGE_PUNCTUATION = /^[^\p{L}\p{N}]+|[^\p{L}\p{N}]+$/gu;
    const CAMEL_CASE_BOUNDARY = /(?<=\p{Ll})(?=\p{Lu})|(?<=\p{Lu})(?=\p{Lu}\p{Ll})|(?<=\p{L})(?=\p{N})|(?<=\p{N})(?=\p{L})/u;

    function trimPunctuation(word) {
        return word.replace(EDGE_PUNCTUATION, "");
    }

    function normalize(term) {
        return term.normalize("NFD").replace(/\p{M}/gu, "").toLowerCase();
    }

    // Splits text into terms. Compound words such as "TimerJobBase.Execute", "x-api-key" or "MSV1_0" are
    // indexed as a whole and as their parts, camel case words such as "TimerJobBase" also as "timer", "job" and "base".
    function tokenize(text) {
        const tokens = new Set();
        for (const word of text.split(/\s+/)) {
            const compound = trimPunctuation(word);
            if (!compound) {
                continue;
            }
            tokens.add(compound);
            for (const part of compound.split(SEPARATOR)) {
                if (part !== compound) {
                    tokens.add(part);
                }
                for (const subPart of part.split(CAMEL_CASE_BOUNDARY)) {
                    if (subPart.length > 1 && subPart !== part) {
                        tokens.add(subPart);
                    }
                }
            }
        }
        return [...tokens];
    }

    // Splits a query into terms. Compound words match either the compound itself or all of its parts.
    // The last word is matched as prefix, as the user might still be typing it.
    function parseQuery(query) {
        const words = query.split(/\s+/).map(trimPunctuation).filter(Boolean);
        const meaningful = words.filter(word => !STOP_WORDS.has(word.toLowerCase()));
        return (meaningful.length > 0 ? meaningful : words).map((word, i, all) => {
            const parts = word.split(SEPARATOR).filter(Boolean);
            const queries = parts.length > 1 ? [word, { combineWith: "AND", queries: parts }] : [word];
            return { combineWith: "OR", queries, prefix: i === all.length - 1 && (term => term.length > 1) };
        });
    }

    const SEARCH_OPTIONS = {
        boost: { title: 5, headings: 2, text: 1 },
        weights: { prefix: 0.2, fuzzy: 0.3 },
        boostDocument: (id, term, storedFields) => storedFields.api ? 0.3 : 1,
        // Terms are already split by parseQuery
        tokenize: term => [term],
    };

    // Pages titled like the query or containing it as exact phrase are ranked higher
    const PHRASE_BOOST = { exactTitle: 4, title: 3, text: 2 };

    // Tries strict matching first and only relaxes it if nothing is found
    const STRATEGIES = [
        { combineWith: "AND" },
        { combineWith: "AND", fuzzy: term => term.length > 4 ? 0.2 : false },
        { combineWith: "OR", partial: true },
    ];

    const textMaps = new WeakMap();
    const textTokens = new WeakMap();

    function normalizedTextWithMap(text) {
        const normalizedParts = [];
        const starts = [];
        const ends = [];
        const sourceToNormalized = new Array(text.length + 1);
        let normalizedOffset = 0;

        for (const chunkMatch of text.matchAll(/\S+|\s+/gu)) {
            const chunk = chunkMatch[0];
            const chunkStart = chunkMatch.index;
            const normalizedChunk = normalize(chunk);
            normalizedParts.push(normalizedChunk);
            let sourceOffset = 0;

            for (const character of chunk) {
                const sourceStart = chunkStart + sourceOffset;
                const sourceEnd = sourceStart + character.length;
                const normalizedCharacter = normalize(character);
                const normalizedStart = normalizedOffset;

                for (let i = 0; i < character.length; i++) {
                    sourceToNormalized[sourceStart + i] = normalizedStart;
                }
                normalizedOffset += normalizedCharacter.length;
                sourceToNormalized[sourceEnd] = normalizedOffset;

                if (normalizedCharacter.length > 0) {
                    for (let i = normalizedStart; i < normalizedOffset; i++) {
                        starts[i] = sourceStart;
                        ends[i] = sourceEnd;
                    }
                } else if (starts.length > 0) {
                    ends[ends.length - 1] = sourceEnd;
                }
                sourceOffset += character.length;
            }
        }

        sourceToNormalized[text.length] = normalizedOffset;
        return { text: normalizedParts.join(""), starts, ends, sourceToNormalized };
    }

    function indexedTokens(text) {
        const tokens = [];
        const add = (value, start) => {
            let end = start + value.length;
            while (end < text.length && /\p{M}/u.test(String.fromCodePoint(text.codePointAt(end)))) {
                end += String.fromCodePoint(text.codePointAt(end)).length;
            }
            tokens.push({ start, end, normalized: normalize(value) });
        };

        for (const wordMatch of text.matchAll(/\S+/gu)) {
            const word = wordMatch[0];
            const compound = trimPunctuation(word);
            if (!compound) {
                continue;
            }
            const compoundStart = word.indexOf(compound);
            const absoluteStart = wordMatch.index + compoundStart;
            add(compound, absoluteStart);

            for (const partMatch of compound.matchAll(/[\p{L}\p{N}]+/gu)) {
                const part = partMatch[0];
                const partStart = absoluteStart + partMatch.index;
                if (part !== compound) {
                    add(part, partStart);
                }
                let subPartOffset = 0;
                for (const subPart of part.split(CAMEL_CASE_BOUNDARY)) {
                    const subPartStart = partStart + subPartOffset;
                    if (subPart.length > 1 && subPart !== part) {
                        add(subPart, subPartStart);
                    }
                    subPartOffset += subPart.length;
                }
            }
        }
        return tokens;
    }

    function entryTextMap(entry) {
        if (!textMaps.has(entry)) {
            textMaps.set(entry, normalizedTextWithMap(entry.text));
        }
        return textMaps.get(entry);
    }

    function entryTextTokens(entry) {
        if (!textTokens.has(entry)) {
            textTokens.set(entry, indexedTokens(entry.text));
        }
        return textTokens.get(entry);
    }

    function createIndex(entries) {
        const index = new MiniSearch({
            idField: "id",
            fields: ["title", "headings", "text"],
            storeFields: ["api"],
            tokenize,
            processTerm: normalize,
            searchOptions: SEARCH_OPTIONS,
        });
        index.addAll(entries.map((entry, id) => ({
            id,
            title: entry.title,
            headings: entry.sections.map(section => section.title).join(" "),
            text: entry.text,
            api: entry.api,
        })));
        return index;
    }

    // Finds the indexed token position where the phrase or most matched terms occur close together
    function findBestMatch(textMap, phrase, terms, tokens) {
        const text = textMap.text;
        const termSet = new Set(terms);
        const candidates = tokens
            .filter(token => termSet.has(token.normalized))
            .map(token => {
                const normalizedPosition = textMap.sourceToNormalized[token.start];
                const normalizedEnd = textMap.sourceToNormalized[token.end];
                return {
                    position: textMap.starts[normalizedPosition],
                    end: textMap.ends[normalizedEnd - 1],
                    normalizedPosition,
                    normalizedEnd,
                    term: text.slice(normalizedPosition, normalizedEnd),
                };
            })
            .sort((a, b) => a.normalizedPosition - b.normalizedPosition);

        if (phrase) {
            const phraseStart = text.indexOf(phrase);
            if (phraseStart >= 0) {
                const starts = new Set(tokens.map(token => textMap.sourceToNormalized[token.start]));
                const ends = new Set(tokens.map(token => textMap.sourceToNormalized[token.end]));
                const phraseEnd = phraseStart + phrase.length;
                if (starts.has(phraseStart) && ends.has(phraseEnd)) {
                    return {
                        position: textMap.starts[phraseStart],
                        end: textMap.ends[phraseEnd - 1],
                        normalizedPosition: phraseStart,
                        normalizedEnd: phraseEnd,
                    };
                }
            }
        }

        const windowSize = 200;
        let best = null;
        let left = 0;
        let right = 0;
        let distinctTerms = 0;
        const termCounts = new Map();
        for (const candidate of candidates) {
            const windowStart = candidate.normalizedPosition - windowSize / 2;
            const windowEnd = candidate.normalizedPosition + windowSize / 2;
            while (right < candidates.length && candidates[right].normalizedPosition < windowEnd) {
                const term = candidates[right++].term;
                const count = termCounts.get(term) || 0;
                if (count === 0) {
                    distinctTerms++;
                }
                termCounts.set(term, count + 1);
            }
            while (left < right && candidates[left].normalizedPosition <= windowStart) {
                const term = candidates[left++].term;
                const count = termCounts.get(term) - 1;
                if (count === 0) {
                    termCounts.delete(term);
                    distinctTerms--;
                } else {
                    termCounts.set(term, count);
                }
            }
            if (!best || distinctTerms > best.count) {
                best = { ...candidate, count: distinctTerms };
            }
        }
        return best;
    }

    function escapeHtml(text) {
        return text.replace(/[&<>"']/g, c => ({ "&": "&amp;", "<": "&lt;", ">": "&gt;", "\"": "&quot;", "'": "&#39;" })[c]);
    }

    function highlight(text, terms) {
        if (terms.length === 0) {
            return escapeHtml(text);
        }
        const termSet = new Set(terms);
        const matches = indexedTokens(text)
            .filter(token => termSet.has(token.normalized))
            .sort((a, b) => a.start - b.start || b.end - a.end);
        let html = "";
        let last = 0;
        let matchEnd = -1;
        for (const match of matches) {
            if (match.start < matchEnd) {
                if (match.end > matchEnd) {
                    html += escapeHtml(text.slice(matchEnd, match.end));
                    matchEnd = match.end;
                }
                continue;
            }
            html += escapeHtml(text.slice(last, match.start)) + "<mark>" + escapeHtml(text.slice(match.start, match.end)) + "</mark>";
            last = match.end;
            matchEnd = match.end;
        }
        return html + escapeHtml(text.slice(last));
    }

    // Text fragment (https://developer.mozilla.org/en-US/docs/Web/URI/Fragment/Text_fragments) of the whole words
    // at the given position, so the browser scrolls to and highlights the match
    function textFragment(text, position, end, normalizedText) {
        let start = position;
        let fragmentEnd = end;
        while (start > 0 && !/\s/.test(text[start - 1])) {
            start--;
        }
        while (fragmentEnd < text.length && !/\s/.test(text[fragmentEnd])) {
            fragmentEnd++;
        }
        const word = trimPunctuation(text.slice(start, fragmentEnd));
        const normalizedWord = normalize(word);
        if (!normalizedWord || normalizedText.indexOf(normalizedWord) !== normalizedText.lastIndexOf(normalizedWord)) {
            return "";
        }
        return ":~:text=" + encodeURIComponent(word).replace(/-/g, "%2D");
    }

    function resultScore(entry, searchResult, normalizedQuery, phrase) {
        let score = searchResult.score;
        if (normalize(entry.title) === normalizedQuery) {
            score *= PHRASE_BOOST.exactTitle;
        } else if (phrase && normalize(entry.title).includes(phrase)) {
            score *= PHRASE_BOOST.title;
        } else if (phrase && normalize(entry.text).includes(phrase)) {
            score *= PHRASE_BOOST.text;
        }
        return score;
    }

    function createResult(entry, searchResult, score, phrase) {
        // Single characters are only matched as part of compound words and would be highlighted everywhere
        const terms = Object.keys(searchResult.match).filter(term => term.length > 1);
        const textMap = entryTextMap(entry);
        const match = findBestMatch(textMap, phrase, terms, entryTextTokens(entry));

        let snippet = entry.text.slice(0, 200);
        let section = null;
        let fragment = "";
        if (match) {
            const start = Math.max(0, entry.text.lastIndexOf(" ", Math.max(0, match.position - 80)) + 1);
            const end = entry.text.indexOf(" ", Math.min(entry.text.length, start + 220));
            snippet = (start > 0 ? "… " : "") + entry.text.slice(start, end < 0 ? undefined : end) + (end < 0 ? "" : " …");
            section = entry.sections.filter(s => s.offset <= match.position).pop() || null;
            fragment = textFragment(entry.text, match.position, match.end, textMap.text);
        }

        const anchor = (section ? section.id : "") + fragment;
        return {
            link: entry.link + (anchor ? "#" + anchor : ""),
            titleHtml: highlight(entry.title, terms),
            sectionHtml: section ? highlight(section.title, terms) : null,
            snippetHtml: highlight(snippet, terms),
            api: entry.api,
            score,
        };
    }

    function search(index, entries, query, limit = 50) {
        const queries = parseQuery(query);
        if (queries.length === 0) {
            return { results: [], total: 0, partial: false };
        }
        const words = query.split(/\s+/).map(trimPunctuation).filter(Boolean);
        const normalizedQuery = normalize(words.join(" "));
        const phrase = words.length > 1 ? normalizedQuery : null;
        for (const strategy of STRATEGIES) {
            const found = index.search({ combineWith: strategy.combineWith, queries }, strategy);
            if (found.length > 0) {
                const ranked = found.map(searchResult => {
                    const entry = entries[searchResult.id];
                    return {
                        entry,
                        searchResult,
                        score: resultScore(entry, searchResult, normalizedQuery, phrase),
                    };
                }).sort((a, b) => b.score - a.score);
                return {
                    results: ranked.slice(0, limit).map(result =>
                        createResult(result.entry, result.searchResult, result.score, phrase)),
                    total: found.length,
                    partial: !!strategy.partial,
                };
            }
        }
        return { results: [], total: 0, partial: false };
    }

    async function load(url) {
        const response = await fetch(url);
        if (!response.ok) {
            throw new Error(`Loading search data failed: ${response.status} ${response.statusText}`);
        }
        const entries = await new Response(response.body.pipeThrough(new DecompressionStream("gzip"))).json();
        const index = createIndex(entries);
        return { search: query => search(index, entries, query) };
    }

    return { load, createIndex, search, tokenize, parseQuery };
});
